 static int checks;
 static void Check(bool ok,string label){if(!ok)throw new Exception("L FAIL: "+label);checks++;Console.WriteLine("L PASS: "+label);}
 static DemoWorld World(){var w=new DemoWorld();w.NewGame(0);w.SimulationPaused=true;w.Player.CargoMax=100000;return w;}
