   var missileNpc=tactical.Targets.First(t=>tr.Npcs.GetValueOrDefault(t.Id)?.Role=="missile");missileNpc.Position=tactical.Player.Position+Vector3.UnitX*500;missileNpc.LockId="player";int loaded=missileNpc.Profile!.Weapons[0].Loaded;tactical.UpdateNpcCombatB(.01f);Check(tactical.MissilesInFlight.Any(missile=>missile.Owner==missileNpc.Id)&&missileNpc.Profile.Weapons[0].Loaded==loaded-1,"NPC missile archetype launches a real projectile and consumes magazine ammunition");
   var outsider=World();var om=Relay(outsider);var victim=outsider.Targets.First(t=>t.Id==om.WarpId+":0:0:0");decimal outsideBalance=outsider.Balance;outsider.DamageEncounterAuditL(victim,"unrelated-hostile");Check(outsider.Balance==outsideBalance&&om.GraphL!.Drops[victim.Id].Owner=="unrelated-hostile"&&om.GraphL.Drops[victim.Id].BountyShares.Count==0,"unrelated NPC kill does not award the player's bounty or wreck ownership");
   var share=World();share.EnsurePopulationC();var crew=share.Population.Pilots.Take(2).ToArray();foreach(var p in crew){p.Contracted=true;p.Suspended=false;p.Status="Recruited";p.System=share.SystemId;}Check(share.RequestRelayL()=="","sharing contract offer created");var sm=share.AgentsState.Missions.Last();Check(share.SetMissionSharingL(sm.Id,true)==""&&sm.GraphL!.SharePilots.Count>=2,"sharing freezes explicitly contracted pilot IDs");share.AcceptMission38(sm.Id);sm.Cargo=1;sm.ObjectiveDone=true;decimal playerMoney=share.Balance;var wallets=crew.ToDictionary(p=>p.Id,p=>p.Wallet);Check(share.CompleteMission38(sm.Id)=="","shared mission settles through agent authority");var receipt=sm.GraphL!.Settlement!;Check(receipt.Money.Values.Sum()==receipt.Total&&receipt.Loyalty.Values.Sum()==sm.LP,"fleet money and integer LP shares conserve totals");Check(crew.All(p=>p.Wallet> wallets[p.Id]&&p.MissionLoyaltyL.ContainsKey(sm.Contact.Corporation))&&share.Balance-playerMoney==receipt.Money["player"],"NPC fleet shares credit persistent wallets and issuer LP");Check(crew.All(p=>p.MissionStandingsL.ContainsKey(sm.Agent)),"NPC fleet standing shares are persistent recipient records");var bountyShare=World();bountyShare.EnsurePopulationC();var bountyCrew=bountyShare.Population.Pilots.Take(2).ToArray();foreach(var p in bountyCrew){p.Contracted=true;p.Suspended=false;p.Status="Recruited";p.System=bountyShare.SystemId;}bountyShare.RequestRelayL();var bm=bountyShare.AgentsState.Missions.Last();bountyShare.SetMissionSharingL(bm.Id,true);bountyShare.AcceptMission38(bm.Id);bountyShare.Undock();bountyShare.EnterGrid(bm.WarpId,false);var bt=bountyShare.Targets.First(t=>t.Id==bm.WarpId+":0:0:0");bountyShare.DamageMissionAudit38(bt);var bd=bm.GraphL!.Drops[bt.Id];Check(bd.BountyShares.Count>=3&&bd.BountyShares.Values.Sum()==90,"fleet bounty shares preserve total and persistent recipient identities");var bw=bountyShare.Targets.First(t=>t.Id=="wreck_"+bt.Id);bw.Contents.Clear();bw.Salvage=0;bountyShare.Save();var bountyLoad=new DemoWorld();Check(bountyLoad.Load()&&bountyLoad.Targets.First(t=>t.Id==bw.Id).Contents.Count==0&&bountyLoad.AgentsState.Missions.Last().GraphL!.Drops[bt.Id].Salvage==0,"looted and salvaged wreck depletion survives reload without reroll");
   share.Save();var sharedLoad=new DemoWorld();Check(sharedLoad.Load()&&sharedLoad.AgentsState.Missions.Last().GraphL!.Settlement!.Money.Values.Sum()==receipt.Total,"fleet-sharing receipt survives save reload");
   var late=World();var lateMission=Relay(late);late.EnterGrid("station",false);late.Screen=ViewMode.Station;lateMission.Cargo=1;lateMission.ObjectiveDone=true;late.SimulationUtc=lateMission.BonusUntil.AddSeconds(1);decimal lateBalance=late.Balance;Check(late.CompleteMission38(lateMission.Id)==""&&late.Balance==lateBalance+lateMission.Reward,"expired time bonus does not pay while mission remains valid");
