 static void CheckGraph(GraphDefinitionL graph,string id){string error=GraphCompilerL.Validate(graph);if(error.Length>0)throw new Exception("L catalogue graph "+id+": "+error);}
}

public sealed partial class DemoWorld { internal void DamageEncounterAuditL(SpaceTarget target,string source)=>ApplyPacket(target,DamagePacket.Single(10000000,DamageType.EM),false,source); }
